WITH filtered AS (SELECT id, balance, opened_date, status, UPPER(status) AS status_upper, CASE WHEN status = 'CLOSED' THEN 1 ELSE 0 END AS is_closed, COALESCE(status, 'OTHER') AS status_clean FROM accounts WHERE account_type NOT IN ('SAVINGS', 'CREDIT') AND customer_id IS NOT NULL) SELECT s.*, top1.txn_time FROM filtered s JOIN LATERAL (SELECT c.txn_time FROM transactions c WHERE c.account_id = s.id ORDER BY c.amount DESC, c.id DESC LIMIT 1) top1 ON TRUE;
